    /// <summary>
    /// Coc to disable the edit button when the invoice is in workflow
    /// </summary>
    void setButtonAccessMultiSelect()
    {
        next setButtonAccessMultiSelect();

        VendInvoiceInfoListPageMultiSelect vendInvoiceInfoListPageMultiSelect = VendInvoiceInfoListPageMultiSelect::determineMultiSelectState(vendInvoiceInfoTable_ds, VendInvoiceInfoTable, vendInvoiceListPageState);

        if (vendInvoiceInfoListPageMultiSelect.parmRecordsMarked())
        {
            this.enableGridDefaultAction(vendInvoiceInfoListPageMultiSelect.parmShouldBeEnabled() &&
                                         !vendInvoiceInfoListPageMultiSelect.parmInWorkflowReviewOrRejected());
        }
    }

    /// <summary>
    /// refresh after worklfow submit, doing a research as reread of the datasource was not disabling some functions
    /// </summary>
    public void refreshAfterWorkflowSubmit()
    {
        next refreshAfterWorkflowSubmit();

        vendInvoiceInfoTable_ds.research(true);
        vendInvoiceInfoTable_ds.refresh();
    }
